import Icon from 'flarum/common/components/Icon';
import { Avatar, due, onColor, t, tx } from '../util';
export const PRIORITY_CLASS = {
  urgent: 'is-urgent',
  high: 'is-high',
  normal: 'is-normal',
  low: 'is-low'
};

/** What a card shows on the board: labels, title, due, priority, checklist, comments, people. */
export const CardFace = {
  view(vnode) {
    const {
      card,
      data,
      moving
    } = vnode.attrs;
    return [card.coverColor ? m("div", {
      className: "CorkboardCard-cover",
      style: {
        background: card.coverColor
      }
    }) : null, moving ? m("div", {
      className: "CorkboardCard-moving"
    }, t('board.moving', {
      name: moving
    })) : null, labels(card, data), m("div", {
      className: "CorkboardCard-title"
    }, card.completedAt ? m(Icon, {
      name: "fas fa-check",
      className: "CorkboardCard-check"
    }) : null, card.title), m("div", {
      className: "CorkboardCard-meta"
    }, dueAndPriority(card), stats(card), m("span", {
      className: "CorkboardCard-people"
    }, card.assigneeIds.slice(0, 3).map(id => m(Avatar, {
      user: data.users[id],
      size: 22,
      ring: true
    })), card.assigneeIds.length > 3 ? m("span", {
      className: "CorkboardCard-more"
    }, "+", card.assigneeIds.length - 3) : null))];
  }
};
function labels(card, data) {
  const list = card.labelIds.map(id => data.labels.find(l => l.id === id)).filter(Boolean);
  if (!list.length) return null;
  return m("div", {
    className: "CorkboardCard-labels"
  }, list.map(l => m("span", {
    className: "CorkboardLabel",
    style: {
      background: l.color,
      color: onColor(l.color)
    },
    title: l.name
  }, l.name || ' ')));
}
function dueAndPriority(card) {
  const when = due(card);
  return [when ? m("span", {
    className: 'CorkboardDue is-' + when.state
  }, m(Icon, {
    name: "far fa-calendar"
  }), when.text) : null, card.priority !== 'none' ? m("span", {
    className: 'CorkboardPriority ' + PRIORITY_CLASS[card.priority]
  }, m("span", {
    className: "CorkboardPriority-dot"
  }), t('priority.' + card.priority)) : null];
}

/** The checklist, comment and linked-discussion counts. */
function stats(card) {
  return [card.checklistTotal ? m("span", {
    className: 'CorkboardCard-stat' + (card.checklistDone === card.checklistTotal ? ' is-complete' : ''),
    title: tx('card.checklist_count', {
      done: card.checklistDone,
      total: card.checklistTotal
    })
  }, m(Icon, {
    name: "far fa-square-check"
  }), card.checklistDone, "/", card.checklistTotal) : null, card.commentCount ? m("span", {
    className: "CorkboardCard-stat"
  }, m(Icon, {
    name: "far fa-comment"
  }), card.commentCount) : null, card.discussionId ? m("span", {
    className: "CorkboardCard-stat",
    title: tx('card.has_discussion')
  }, m(Icon, {
    name: "fas fa-link"
  })) : null];
}
flarum.reg.add('ernestdefoe-corkboard', 'forum/components/CardFace', { PRIORITY_CLASS: PRIORITY_CLASS,CardFace: CardFace, });